171	
172	const QuickAddModal = ({ produto, onFechar, onConfirmar }) => {
173	  const [quantidade, setQuantidade] = useState(1);
174	  const [observacao, setObservacao] = useState('');
175	  const [salvando, setSalvando] = useState(false);
176	
177	  const confirmar = async () => {
178	    setSalvando(true);
179	    try {
180	      await onConfirmar({ product_id: produto.id, quantity: quantidade, observacao: observacao.trim() || undefined });
181	    } finally {
182	      setSalvando(false);
183	    }
184	  };
185	
186	  return (
187	    <div className="fixed inset-0 bg-black/60 flex items-end sm:items-center justify-center z-[60] p-4">
188	      <div className="bg-white rounded-2xl w-full max-w-sm p-5 shadow-2xl">
189	        <div className="flex items-center gap-3 mb-4">
190	          <div className="w-14 h-14 rounded-xl overflow-hidden bg-[#F4F4F5] flex-shrink-0">
191	            {produto.image_url
192	              ? <img src={produto.image_url} alt="" className="w-full h-full object-cover" />
193	              : <div className="w-full h-full flex items-center justify-center"><Icon name="UtensilsCrossed" size={20} className="text-[#A1A1AA]" /></div>}
194	          </div>
195	          <div className="min-w-0">
196	            <p className="text-sm font-bold text-[#18181B] truncate">{produto.name}</p>
197	            <p className="text-xs text-[#71717A]">{fmt(produto.price)}</p>
198	          </div>
199	        </div>
200	
201	        <label className="text-xs text-[#71717A]">Quantidade</label>
202	        <div className="flex items-center gap-3 mt-1 mb-3">
203	          <button onClick={() => setQuantidade((q) => Math.max(1, q - 1))}
204	            className="w-10 h-10 rounded-xl border border-[#E4E4E7] flex items-center justify-center text-lg font-bold text-[#27272A]">−</button>
205	          <span className="text-lg font-bold text-[#18181B] w-8 text-center">{quantidade}</span>
206	          <button onClick={() => setQuantidade((q) => q + 1)}
207	            className="w-10 h-10 rounded-xl border border-[#E4E4E7] flex items-center justify-center text-lg font-bold text-[#27272A]">+</button>
208	        </div>
209	
210	        <label className="text-xs text-[#71717A]">Observação (opcional)</label>
211	        <textarea value={observacao} onChange={(e) => setObservacao(e.target.value)} rows={2}
212	          placeholder="Ex: sem cebola, ponto da carne..."
213	          className="w-full border border-[#E4E4E7] rounded-xl px-3 py-2 text-sm mt-1 mb-4 resize-none" />
214	
215	        <div className="flex gap-2">
216	          <button onClick={onFechar} className="flex-1 py-2.5 text-sm border border-[#E4E4E7] rounded-xl text-[#71717A]">
217	            Cancelar
218	          </button>
219	          <button onClick={confirmar} disabled={salvando}
220	            className="flex-1 py-2.5 text-sm font-bold rounded-xl text-white bg-[#FF441F] hover:bg-[#E63A19] disabled:opacity-50">
221	            {salvando ? 'Adicionando...' : 'Adicionar'}
222	          </button>
223	        </div>
224	      </div>
225	    </div>
226	  );
227	};
228	
229	const ProdutoPickerModal = ({ produtos, onFechar, onAdicionado }) => {
230	  const [busca, setBusca] = useState('');
231	  const [categoria, setCategoria] = useState('todas');
232	  const [produtoAtivo, setProdutoAtivo] = useState(null);
233	
234	  const categorias = ['todas', ...new Set(produtos.map((p) => p.category_name ?? 'Outros'))];
235	  const filtrados = produtos.filter((p) => {
236	    const bateBusca = p.name.toLowerCase().includes(busca.toLowerCase());
237	    const bateCategoria = categoria === 'todas' || (p.category_name ?? 'Outros') === categoria;
238	    return bateBusca && bateCategoria;
239	  });
240	
241	  return (
242	    <div className="fixed inset-0 bg-white z-50 flex flex-col">
243	      <div className="p-4 border-b border-[#E4E4E7] sticky top-0 bg-white max-w-2xl w-full mx-auto">
244	        <div className="flex items-center gap-2 mb-3">
245	          <button onClick={onFechar} className="p-1 text-[#71717A]"><Icon name="ArrowLeft" size={20} /></button>
246	          <h2 className="text-base font-bold text-[#18181B]">Adicionar produto</h2>
247	        </div>
248	        <div className="relative">
249	          <Icon name="Search" size={16} className="absolute left-3 top-1/2 -translate-y-1/2 text-[#A1A1AA]" />
250	          <input value={busca} onChange={(e) => setBusca(e.target.value)} placeholder="Buscar produto..." autoFocus
251	            className="w-full border border-[#E4E4E7] rounded-xl pl-9 pr-3 py-2.5 text-sm focus:outline-none focus:border-[#FF441F]" />
252	        </div>
253	        <div className="flex gap-1.5 mt-3 overflow-x-auto pb-1">
254	          {categorias.map((c) => (
255	            <button key={c} onClick={() => setCategoria(c)}
256	              className={`px-3 py-1.5 rounded-full text-xs font-medium whitespace-nowrap flex-shrink-0 ${
257	                categoria === c ? 'bg-[#FF441F] text-white' : 'bg-[#F4F4F5] text-[#71717A]'
258	              }`}>
259	              {c === 'todas' ? 'Todas' : c}
260	            </button>
261	          ))}
262	        </div>
263	      </div>
264	
265	      <div className="flex-1 overflow-y-auto p-4 max-w-2xl w-full mx-auto space-y-2">
266	        {filtrados.map((p) => (
267	          <button key={p.id} onClick={() => setProdutoAtivo(p)}
268	            className="w-full bg-white border border-[#E4E4E7] rounded-xl p-2.5 flex items-center gap-3 text-left active:scale-[0.98] transition-transform">
269	            <div className="w-12 h-12 rounded-lg overflow-hidden bg-[#F4F4F5] flex-shrink-0">
270	              {p.image_url
271	                ? <img src={p.image_url} alt="" className="w-full h-full object-cover" />
272	                : <div className="w-full h-full flex items-center justify-center"><Icon name="UtensilsCrossed" size={18} className="text-[#A1A1AA]" /></div>}
273	            </div>
274	            <div className="min-w-0 flex-1">
275	              <p className="text-sm font-semibold text-[#18181B] truncate">{p.name}</p>
276	              <p className="text-xs text-[#71717A]">{fmt(p.price)}</p>
277	            </div>
278	            <Icon name="Plus" size={18} className="text-[#FF441F] flex-shrink-0" />
279	          </button>
280	        ))}
281	        {filtrados.length === 0 && <p className="text-sm text-[#A1A1AA] text-center py-6">Nenhum produto encontrado.</p>}
282	      </div>
283	
284	      {produtoAtivo && (
285	        <QuickAddModal
286	          produto={produtoAtivo}
287	          onFechar={() => setProdutoAtivo(null)}
288	          onConfirmar={async (item) => { await onAdicionado(item); setProdutoAtivo(null); }}
289	        />
290	      )}
291	    </div>
292	  );
293	};
294	
295	const PagamentoParcial = ({ comanda, onRegistrado, podePagamentoParcial }) => {
296	  const [valor, setValor] = useState('');
297	  const [forma, setForma] = useState('pix');
298	  const [valorRecebido, setValorRecebido] = useState('');
299	  const [erro, setErro] = useState(null);
300	  const [salvando, setSalvando] = useState(false);
301	
302	  const saldo = comanda.saldo?.saldo ?? 0;
303	  const troco = forma === 'cash' && valorRecebido ? Number(valorRecebido) - Number(valor || 0) : null;
304	
305	  const registrar = async () => {
306	    const v = Number(valor);
307	    if (!v || v <= 0) return;
308	    if (forma === 'cash' && valorRecebido && Number(valorRecebido) < v) {
309	      setErro('Valor recebido não pode ser menor que o valor a pagar.');
310	      return;
311	    }
312	    setErro(null);
313	    setSalvando(true);
314	    try {
315	      await registrarPagamento(comanda.id, v, forma, forma === 'cash' && valorRecebido ? Number(valorRecebido) : undefined);
316	      setValor('');
317	      setValorRecebido('');
318	      await onRegistrado();
319	    } catch (err) {
320	      setErro(err.message ?? 'Não foi possível registrar o pagamento.');
321	    } finally {
322	      setSalvando(false);
323	    }
324	  };
325	
326	  return (
327	    <div className="bg-white rounded-xl border border-[#E4E4E7] p-3 space-y-2">
328	      <div className="flex justify-between text-sm">
329	        <span className="text-[#71717A]">Saldo devedor</span>
330	        <strong className={saldo > 0.01 ? 'text-[#FF441F]' : 'text-emerald-600'}>{fmt(saldo)}</strong>
331	      </div>
332	      {(comanda.pagamentos ?? []).length > 0 && (
333	        <div className="space-y-0.5">
334	          {comanda.pagamentos.map((p) => (
335	            <p key={p.id} className="text-xs text-[#71717A] flex justify-between">
336	              <span>{PAGAMENTO_LABEL[p.forma_pagamento] ?? p.forma_pagamento} ({p.origem === 'garcom' ? 'garçom' : 'caixa'})</span>
337	              <span>{fmt(p.valor)}</span>
338	            </p>
339	          ))}
340	        </div>
341	      )}
342	      {saldo > 0.01 && podePagamentoParcial && (
343	        <div className="space-y-1.5 pt-1">
344	          <div className="flex items-center gap-1.5">
345	            <input type="number" value={valor} onChange={(e) => setValor(e.target.value)} placeholder="Valor"
346	              className="w-20 border border-[#E4E4E7] rounded-lg px-2 py-1.5 text-xs" />
347	            <select value={forma} onChange={(e) => setForma(e.target.value)}
348	              className="flex-1 border border-[#E4E4E7] rounded-lg px-2 py-1.5 text-xs">
349	              <option value="pix">PIX</option>
350	              <option value="credit_card">Cartão de crédito</option>
351	              <option value="debit_card">Cartão de débito</option>
352	              <option value="cash">Dinheiro</option>
353	            </select>
354	            <button onClick={registrar} disabled={salvando || !valor}
355	              className="px-2.5 py-1.5 bg-zinc-800 text-white rounded-lg text-xs font-bold disabled:opacity-40 flex-shrink-0">
356	              Pagar
357	            </button>
358	          </div>
359	          {forma === 'cash' && (
360	            <div className="flex items-center gap-1.5">
361	              <input type="number" value={valorRecebido} onChange={(e) => setValorRecebido(e.target.value)}
362	                placeholder="Valor recebido do cliente"
363	                className="flex-1 border border-[#E4E4E7] rounded-lg px-2 py-1.5 text-xs" />
364	              {troco !== null && (
365	                <span className={`text-xs font-bold flex-shrink-0 ${troco < 0 ? 'text-red-600' : 'text-emerald-700'}`}>
366	                  Troco: {fmt(Math.max(troco, 0))}
367	                </span>
368	              )}
369	            </div>
370	          )}
371	        </div>
372	      )}
373	      {saldo > 0.01 && !podePagamentoParcial && (
374	        <p className="text-xs text-[#A1A1AA] pt-1">Você não tem permissão para registrar pagamento parcial.</p>
375	      )}
376	      {erro && <p className="text-xs text-red-600">{erro}</p>}
377	    </div>
378	  );
379	};
380	
381	const ComandaDetalhe = ({ comandaId, onVoltar, podePagamentoParcial }) => {
382	  const [comanda, setComanda] = useState(null);
383	  const [produtos, setProdutos] = useState([]);
384	  const [mostrarPicker, setMostrarPicker] = useState(false);
385	  const [enviando, setEnviando] = useState(false);
386	  const [mostrarFechar, setMostrarFechar] = useState(false);
387	  const [erro, setErro] = useState(null);
388	  const [mostrarQr, setMostrarQr] = useState(false);
389	
390	  const carregar = useCallback(async () => {
391	    const [c, p] = await Promise.all([getComanda(comandaId), getProdutos()]);
392	    setComanda(c);
393	    setProdutos(p);
394	  }, [comandaId]);
395	
396	  useEffect(() => { carregar(); }, [carregar]);
397	
398	  const adicionarProduto = async (item) => {
